// frontend/src/pages/projects/ProjectDetailPage.js
// Real data — no more mock. All tabs wired to API.
import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { projectsAPI, contractsAPI } from '../../services/api';
import { usePermissions } from '../../context/PermissionsContext';
import AppLayout from '../../components/layout/AppLayout';
import toast from 'react-hot-toast';

const T = {
  bg: '#F8F9FA', card: '#FFFFFF', border: '#E8EDF2',
  text: '#1a1f2e', textSub: '#6B7280', textMuted: '#9CA3AF',
  orange: '#F97316', orangeLight: 'rgba(249,115,22,0.1)',
  green: '#10B981', greenLight: 'rgba(16,185,129,0.08)',
  red: '#EF4444', redLight: 'rgba(239,68,68,0.08)',
  blue: '#3B82F6', yellow: '#F59E0B', purple: '#8B5CF6',
  shadow: '0 1px 3px rgba(0,0,0,0.07)',
};

const STATUS_CONFIG = {
  planifie:  { label: 'Planifié',  color: '#6366F1', bg: 'rgba(99,102,241,0.12)'  },
  en_cours:  { label: 'En cours',  color: '#F59E0B', bg: 'rgba(245,158,11,0.12)'  },
  suspendu:  { label: 'Suspendu',  color: '#EF4444', bg: 'rgba(239,68,68,0.12)'   },
  termine:   { label: 'Terminé',   color: '#10B981', bg: 'rgba(16,185,129,0.12)'  },
};

const TYPE_ICONS = {
  batiment:'🏢', route:'🛣️', hydraulique:'💧', electricite:'⚡',
  autre:'🔧', aep:'💧', assainissement:'🚰', pont:'🌉',
};

const PROJECT_TYPES = [
  { value: 'batiment',       label: '🏗️ Bâtiment'     },
  { value: 'route',          label: '🛣️ Route / VRD'  },
  { value: 'aep',            label: '💧 AEP'           },
  { value: 'assainissement', label: '🚰 Assainissement' },
  { value: 'pont',           label: '🌉 Pont'           },
  { value: 'hydraulique',    label: '🌊 Hydraulique'    },
  { value: 'electricite',    label: '⚡ Électricité'    },
  { value: 'autre',          label: '📦 Autre'          },
];

// ── Components ──────────────────────────────────────────────────────────────

function StatusBadge({ status }) {
  const c = STATUS_CONFIG[status] || { label: status, color: '#9CA3AF', bg: '#F3F4F6' };
  return (
    <span style={{ display:'inline-flex', alignItems:'center', gap:5, padding:'4px 12px', borderRadius:100, fontSize:13, fontWeight:600, color:c.color, background:c.bg }}>
      <span style={{ width:7, height:7, borderRadius:'50%', background:c.color }}/>
      {c.label}
    </span>
  );
}

function Card({ children, style={}, p=24 }) {
  return (
    <div style={{ background:T.card, border:`1px solid ${T.border}`, borderRadius:12, padding:p, boxShadow:T.shadow, ...style }}>
      {children}
    </div>
  );
}

function InfoRow({ label, value }) {
  return (
    <div style={{ display:'flex', justifyContent:'space-between', alignItems:'baseline', padding:'10px 0', borderBottom:`1px solid ${T.border}` }}>
      <span style={{ fontSize:13, color:T.textSub }}>{label}</span>
      <span style={{ fontSize:13, fontWeight:600, color:T.text }}>
        {value || <span style={{ color:T.textMuted, fontStyle:'italic', fontWeight:400, fontSize:12 }}>Non renseigné</span>}
      </span>
    </div>
  );
}

function Pbar({ pct, color=T.orange, h=6 }) {
  return (
    <div style={{ height:h, background:T.border, borderRadius:h, overflow:'hidden' }}>
      <div style={{ height:'100%', width:`${Math.min(100,pct||0)}%`, background:color, borderRadius:h, transition:'width 0.6s' }}/>
    </div>
  );
}

function fmtFCFA(n) {
  if (n == null) return '—';
  const v = parseFloat(n);
  if (v >= 1e9) return `${(v/1e9).toFixed(2)} Mrd FCFA`;
  if (v >= 1e6) return `${(v/1e6).toFixed(2)} M FCFA`;
  if (v >= 1e3) return `${(v/1e3).toFixed(0)} K FCFA`;
  return v.toLocaleString('fr-FR') + ' FCFA';
}

// ── Vue Ensemble Tab (Directeur / Admin view) ────────────────────────────────

function VueEnsemble({ project, stats, contracts }) {
  const budget       = parseFloat(project.budget || 0);
  const expenses     = parseFloat(project.actual_expenses || 0);
  const pct          = budget > 0 ? Math.round((expenses / budget) * 100) : 0;
  const contractsTotal = stats?.contracts_total || 0;
  const tasks        = stats?.tasks || [];

  const tasksByStatus = tasks.reduce((acc, t) => {
    acc[t.status] = (acc[t.status] || 0) + 1;
    return acc;
  }, {});

  const TASK_STATUS_LABEL = {
    a_faire:'À faire', en_cours:'En cours', termine:'Terminé', en_retard:'En retard', suspendu:'Suspendu',
  };

  return (
    <div>
      {/* KPI row */}
      <div style={{ display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:16, marginBottom:24 }}>
        {[
          { label:'Avancement global', value:`${project.progress_pct || 0}%`, color:T.orange },
          { label:'Budget consommé',   value:`${pct}%`,                        color:pct>90?T.red:T.orange, alert:pct>90 },
          { label:'Budget restant',    value:fmtFCFA(budget-expenses),         color:T.green  },
          { label:'Contrats',          value:`${project.contracts?.length??0} contrat(s)`, color:T.blue },
        ].map((k,i)=>(
          <Card key={i} p={20}>
            <div style={{ fontSize:11, color:T.textSub, marginBottom:6, fontWeight:500, textTransform:'uppercase', letterSpacing:'0.4px' }}>{k.label}</div>
            <div style={{ fontSize:28, fontWeight:800, color:k.alert?T.red:k.color, lineHeight:1, marginBottom:8 }}>{k.value}</div>
            <Pbar pct={k.label==='Avancement global'?project.progress_pct||0:k.label==='Budget consommé'?pct:0} color={k.alert?T.red:k.color}/>
          </Card>
        ))}
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1.3fr 1fr', gap:20 }}>
        {/* Left: Budget breakdown */}
        <Card>
          <div style={{ fontSize:14, fontWeight:700, color:T.text, marginBottom:20 }}>📊 Suivi budgétaire</div>
          <div style={{ marginBottom:20 }}>
            <div style={{ display:'flex', justifyContent:'space-between', fontSize:13, marginBottom:8 }}>
              <span style={{ color:T.textSub }}>Budget prévisionnel</span>
              <span style={{ fontWeight:700, color:T.text }}>{fmtFCFA(budget)}</span>
            </div>
            <div style={{ display:'flex', justifyContent:'space-between', fontSize:13, marginBottom:8 }}>
              <span style={{ color:T.textSub }}>Dépenses réelles</span>
              <span style={{ fontWeight:700, color:pct>90?T.red:T.text }}>{fmtFCFA(expenses)}</span>
            </div>
            <div style={{ display:'flex', justifyContent:'space-between', fontSize:13, marginBottom:8 }}>
              <span style={{ color:T.textSub }}>Montant contractuel total</span>
              <span style={{ fontWeight:700, color:T.green }}>{fmtFCFA(contractsTotal)}</span>
            </div>
            <div style={{ marginTop:16 }}>
              <div style={{ display:'flex', justifyContent:'space-between', fontSize:13, marginBottom:6 }}>
                <span style={{ color:T.textSub }}>Consommation</span>
                <span style={{ fontWeight:700, color:pct>90?T.red:T.orange }}>{pct}%</span>
              </div>
              <Pbar pct={pct} color={pct>90?T.red:T.orange} h={10}/>
            </div>
            {budget > 0 && (
              <div style={{ marginTop:12, padding:'10px 14px', background:pct>90?T.redLight:T.greenLight, borderRadius:8, fontSize:13 }}>
                {pct > 90
                  ? <span style={{ color:T.red, fontWeight:600 }}>⚠️ Dépassement budgétaire imminent — {fmtFCFA(expenses - budget)} de dépassement</span>
                  : <span style={{ color:T.green, fontWeight:600 }}>✅ Budget bien maîtrisé — {fmtFCFA(budget - expenses)} restants</span>
                }
              </div>
            )}
          </div>

          {/* Marge bénéficiaire nette — Admin Entreprise only */}
          {contractsTotal > 0 && budget > 0 && (
            <div style={{ paddingTop:16, borderTop:`1px solid ${T.border}` }}>
              <div style={{ fontSize:12, fontWeight:700, color:T.textSub, textTransform:'uppercase', letterSpacing:'0.4px', marginBottom:10 }}>
                💡 Marge bénéficiaire nette
              </div>
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                <div>
                  <div style={{ fontSize:24, fontWeight:800, color:contractsTotal>expenses?T.green:T.red }}>
                    {contractsTotal > expenses ? '+' : ''}{fmtFCFA(contractsTotal - expenses)}
                  </div>
                  <div style={{ fontSize:12, color:T.textMuted, marginTop:2 }}>
                    {contractsTotal > 0 ? Math.round(((contractsTotal-expenses)/contractsTotal)*100) : 0}% de marge sur contrats
                  </div>
                </div>
                <div style={{ width:70, height:70, borderRadius:'50%', border:`6px solid ${contractsTotal>expenses?T.green:T.red}`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:13, fontWeight:800, color:contractsTotal>expenses?T.green:T.red }}>
                  {contractsTotal > 0 ? Math.round(((contractsTotal-expenses)/contractsTotal)*100) : 0}%
                </div>
              </div>
            </div>
          )}
        </Card>

        {/* Right: Tasks & Contracts */}
        <div style={{ display:'flex', flexDirection:'column', gap:16 }}>
          {/* Tasks summary */}
          <Card>
            <div style={{ fontSize:14, fontWeight:700, color:T.text, marginBottom:16 }}>📋 Tâches planifiées</div>
            {tasks.length === 0 ? (
              <div style={{ textAlign:'center', padding:'16px 0', color:T.textMuted, fontSize:13 }}>
                Aucune tâche — créez un planning
              </div>
            ) : (
              <>
                {Object.entries(tasksByStatus).map(([status, count]) => (
                  <div key={status} style={{ display:'flex', alignItems:'center', gap:10, marginBottom:8 }}>
                    <div style={{ width:8, height:8, borderRadius:'50%', background:
                      status==='termine'?T.green:status==='en_retard'?T.red:status==='en_cours'?T.orange:T.textMuted, flexShrink:0 }}/>
                    <span style={{ flex:1, fontSize:13, color:T.text }}>{TASK_STATUS_LABEL[status]||status}</span>
                    <span style={{ fontSize:13, fontWeight:700, color:T.textSub }}>{count}</span>
                  </div>
                ))}
                <div style={{ marginTop:10, paddingTop:10, borderTop:`1px solid ${T.border}` }}>
                  <div style={{ fontSize:12, color:T.textMuted }}>
                    Total: {tasks.length} tâche{tasks.length>1?'s':''} · Avancement moyen: {tasks.length>0?Math.round(tasks.reduce((a,t)=>a+(t.progress_pct||0),0)/tasks.length):0}%
                  </div>
                </div>
              </>
            )}
          </Card>

          {/* Contracts list */}
          <Card>
            <div style={{ fontSize:14, fontWeight:700, color:T.text, marginBottom:16 }}>📄 Contrats IA</div>
            {!contracts?.length ? (
              <div style={{ textAlign:'center', padding:'12px 0', color:T.textMuted, fontSize:13 }}>
                Aucun contrat — téléverser un PDF
              </div>
            ) : contracts.slice(0,3).map(c => {
              const montant = c.summary?.montant_total || c.summary?.section2?.conditions_financieres?.montant_ttc;
              return (
                <div key={c.id} style={{ display:'flex', alignItems:'center', gap:10, padding:'8px 0', borderBottom:`1px solid ${T.border}` }}>
                  <span style={{ fontSize:18 }}>📕</span>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontSize:12, fontWeight:600, color:T.text, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{c.file_name}</div>
                    {montant && <div style={{ fontSize:11, color:T.orange, fontWeight:600 }}>{montant}</div>}
                  </div>
                  <span style={{ fontSize:11, color:c.is_validated?T.green:T.yellow, fontWeight:600 }}>
                    {c.is_validated?'✅ Validé':'⏳ En attente'}
                  </span>
                </div>
              );
            })}
          </Card>
        </div>
      </div>
    </div>
  );
}

// ── Budget Tab ───────────────────────────────────────────────────────────────

function BudgetTab({ stats, project }) {
  const budget   = parseFloat(project.budget || 0);
  const expenses = parseFloat(project.actual_expenses || 0);
  const consumed = budget > 0 ? Math.min(100, (expenses / budget) * 100) : 0;
  const contractsTotal = stats?.contracts_total || 0;
  const contractCov = budget > 0 ? Math.min(100, (contractsTotal / budget) * 100) : 0;

  const purchases = stats
    ? Object.entries(stats.purchases_by_status || {}).map(([s, count]) => ({ status: s, count }))
    : [];

  if (!stats) return (
    <Card style={{ textAlign:'center', padding:'48px 24px' }}>
      <div style={{ fontSize:32, marginBottom:12 }}>📊</div>
      <div style={{ color:T.textSub, fontSize:13 }}>
        Statistiques budgétaires non disponibles.<br />
        Vérifiez la route <code>/api/projects/{'{id}'}/budget-stats/</code>
      </div>
    </Card>
  );

  return (
    <div>
      <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:16, marginBottom:24 }}>
        {[
          { label:'Budget prévisionnel',  value:fmtFCFA(budget),         color:'#6366F1', icon:'💼' },
          { label:'Dépenses réelles',     value:fmtFCFA(expenses),       color:consumed>85?T.red:T.orange, icon:'💸', alert:consumed>85 },
          { label:'Montant des contrats', value:fmtFCFA(contractsTotal), color:T.green, icon:'📄' },
        ].map((s,i) => (
          <Card key={i} p={20} style={{ borderTop:`2px solid ${s.color}` }}>
            <div style={{ fontSize:22, marginBottom:10 }}>{s.icon}</div>
            <div style={{ fontSize:22, fontWeight:800, color:s.color, marginBottom:4 }}>{s.value}</div>
            <div style={{ fontSize:11, color:T.textSub, textTransform:'uppercase', letterSpacing:'0.5px' }}>{s.label}</div>
          </Card>
        ))}
      </div>
      <Card>
        <div style={{ fontSize:14, fontWeight:700, color:T.text, marginBottom:20 }}>📊 Avancement budgétaire</div>
        <div style={{ marginBottom:20 }}>
          <div style={{ display:'flex', justifyContent:'space-between', fontSize:13, marginBottom:8 }}>
            <span style={{ color:T.textSub }}>Dépenses réelles vs Budget</span>
            <span style={{ fontWeight:700, color:consumed>85?T.red:T.orange }}>{consumed.toFixed(1)}%</span>
          </div>
          <Pbar pct={consumed} color={consumed>85?T.red:T.orange} h={10}/>
          {budget > 0 && (
            <div style={{ fontSize:12, color:T.textMuted, marginTop:6 }}>
              Reste: {fmtFCFA(budget - expenses)} · Écart contrats/budget: {fmtFCFA(contractsTotal - expenses)}
            </div>
          )}
        </div>
        <div>
          <div style={{ display:'flex', justifyContent:'space-between', fontSize:13, marginBottom:8 }}>
            <span style={{ color:T.textSub }}>Couverture contractuelle vs Budget</span>
            <span style={{ fontWeight:700, color:T.green }}>{contractCov.toFixed(1)}%</span>
          </div>
          <Pbar pct={contractCov} color={T.green} h={10}/>
        </div>
        {purchases.length > 0 && (
          <div style={{ marginTop:20, paddingTop:20, borderTop:`1px solid ${T.border}` }}>
            <div style={{ fontSize:13, fontWeight:600, color:T.textSub, marginBottom:12 }}>Bons de commande par statut</div>
            <div style={{ display:'flex', gap:10, flexWrap:'wrap' }}>
              {purchases.map(p => (
                <div key={p.status} style={{ padding:'8px 14px', borderRadius:8, background:'#F9FAFB', border:`1px solid ${T.border}` }}>
                  <div style={{ fontSize:18, fontWeight:800, color:T.text }}>{p.count}</div>
                  <div style={{ fontSize:11, color:T.textMuted, textTransform:'capitalize' }}>{p.status}</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </Card>
    </div>
  );
}

// ── Contracts Tab ────────────────────────────────────────────────────────────

function ContractsTab({ contracts, projectId, onRefresh }) {
  const navigate = useNavigate();
  const handleValidate = async (contractId) => {
    try {
      await contractsAPI.validate(contractId);
      toast.success('Contrat validé');
      onRefresh();
    } catch {
      toast.error('Erreur lors de la validation');
    }
  };

  if (!contracts?.length) return (
    <Card style={{ textAlign:'center', padding:'48px 24px' }}>
      <div style={{ fontSize:48, marginBottom:12 }}>📄</div>
      <div style={{ color:T.textSub, fontSize:14, marginBottom:20 }}>Aucun contrat associé à ce projet.</div>
      <button onClick={() => navigate('/contracts/upload')}
        style={{ padding:'9px 20px', borderRadius:8, background:T.orange, color:'#fff', fontSize:13, fontWeight:600, border:'none', cursor:'pointer', fontFamily:'inherit' }}>
        📤 Téléverser un contrat IA
      </button>
    </Card>
  );

  return (
    <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
      {contracts.map(c => {
        const montant = c.summary?.section2?.conditions_financieres?.montant_ttc || c.summary?.montant_total;
        return (
          <Card key={c.id} p={0}>
            <div style={{ padding:'16px 20px', display:'flex', alignItems:'center', gap:16 }}>
              <span style={{ fontSize:28 }}>{c.file_type==='pdf'?'📕':'📘'}</span>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontWeight:600, fontSize:14, marginBottom:3, color:T.text, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{c.file_name}</div>
                <div style={{ fontSize:12, color:T.textSub }}>
                  {c.file_type?.toUpperCase()} · {c.file_size ? (c.file_size/1024).toFixed(0) + ' KB' : ''} · {new Date(c.created_at).toLocaleDateString('fr-FR')}
                </div>
              </div>
              {montant && (
                <div style={{ textAlign:'right', flexShrink:0 }}>
                  <div style={{ fontSize:11, color:T.textMuted, marginBottom:2 }}>Montant TTC</div>
                  <div style={{ fontSize:14, fontWeight:700, color:T.orange }}>{montant}</div>
                </div>
              )}
              <div style={{ flexShrink:0, display:'flex', flexDirection:'column', gap:6, alignItems:'flex-end' }}>
                {c.is_processing ? (
                  <span style={{ fontSize:12, color:T.yellow }}>⏳ Analyse IA...</span>
                ) : c.is_validated ? (
                  <span style={{ fontSize:12, color:T.green, fontWeight:600 }}>✅ Validé</span>
                ) : (
                  <>
                    <span style={{ fontSize:12, color:T.yellow }}>⏳ En attente validation</span>
                    <button onClick={() => handleValidate(c.id)}
                      style={{ padding:'5px 12px', borderRadius:6, background:T.green, color:'#fff', fontSize:11, fontWeight:600, border:'none', cursor:'pointer', fontFamily:'inherit' }}>
                      ✅ Valider
                    </button>
                  </>
                )}
                <button onClick={() => navigate(`/contracts/${c.id}`)}
                  style={{ padding:'5px 12px', borderRadius:6, border:`1px solid ${T.border}`, background:'#fff', color:T.textSub, fontSize:11, cursor:'pointer', fontFamily:'inherit' }}>
                  Voir détail
                </button>
              </div>
            </div>
          </Card>
        );
      })}
    </div>
  );
}

// ── Journal Tab ──────────────────────────────────────────────────────────────

