  const [loading, setLoading] = useState(true);

  useEffect(() => {
    projectsAPI.getMembers(projectId)
      .then(r => setMembers(r.data || []))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [projectId]);

  const ROLE_CFG = {
    chef_projet:   { label:'Chef de Projet',   color:'#8B5CF6', bg:'#F5F3FF' },
    chef_chantier: { label:'Chef de Chantier', color:'#F97316', bg:'#FFF7ED' },
    chef_equipe:   { label:"Chef d'Équipe",    color:'#F59E0B', bg:'#FFFBEB' },
    ingenieur:     { label:'Ingénieur',         color:'#10B981', bg:'#ECFDF5' },
    qhse:          { label:'QHSE',              color:'#EF4444', bg:'#FEF2F2' },
    magasinier:    { label:'Magasinier',        color:'#6B7280', bg:'#F3F4F6' },
    comptable:     { label:'Comptable',         color:'#10B981', bg:'#ECFDF5' },
    client:        { label:'Client MO',         color:'#3B82F6', bg:'#EFF6FF' },
  };

  if (loading) return <div style={{ color:T.textSub, padding:24 }}>Chargement...</div>;

  return (
    <Card>
      <div style={{ fontSize:14, fontWeight:700, color:T.text, marginBottom:20 }}>
        👥 Membres du projet ({members.length})
      </div>
      {members.length === 0 ? (
        <div style={{ textAlign:'center', padding:'40px 0', color:T.textMuted }}>
          <div style={{ fontSize:36, marginBottom:12 }}>👥</div>
          <div>Aucun membre assigné à ce projet</div>
        </div>
      ) : (
        <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(260px,1fr))', gap:12 }}>
          {members.map(m => {
            const rc = ROLE_CFG[m.role] || { label:m.role, color:T.textSub, bg:T.border };
            return (
              <div key={m.id} style={{ padding:'14px 16px', border:`1px solid ${T.border}`, borderRadius:10, display:'flex', alignItems:'center', gap:12 }}>
                <div style={{ width:38, height:38, borderRadius:'50%', background:rc.bg, display:'flex', alignItems:'center', justifyContent:'center', fontSize:13, fontWeight:700, color:rc.color, flexShrink:0 }}>
                  {m.user_name?.slice(0,2).toUpperCase() || '??'}
                </div>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontSize:13, fontWeight:600, color:T.text, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{m.user_name || m.user_email}</div>
                  <span style={{ padding:'2px 8px', borderRadius:100, fontSize:11, fontWeight:600, color:rc.color, background:rc.bg }}>{rc.label}</span>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </Card>
  );
}

// ── MAIN ─────────────────────────────────────────────────────────────────────

export default function ProjectDetailPage() {
  const { id }       = useParams();
  const navigate     = useNavigate();
  const { role, canViewFinancials } = usePermissions();

  const [project, setProject]     = useState(null);
  const [stats, setStats]         = useState(null);
  const [loading, setLoading]     = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  const [editing, setEditing]     = useState(false);
  const [editForm, setEditForm]   = useState({});
  const [saving, setSaving]       = useState(false);

  const isAdminOrDirecteur = ['app_owner','admin_entreprise','office_admin'].includes(role);

  const loadProject = () => {
    projectsAPI.get(id)
      .then(res => {
        setProject(res.data);
        setEditForm(res.data);
        projectsAPI.getBudgetStats(id)
          .then(sRes => setStats(sRes.data))
          .catch(() => setStats(null));
      })
      .catch(() => { toast.error('Projet introuvable'); navigate('/projects'); })
      .finally(() => setLoading(false));
  };

  useEffect(() => { setLoading(true); loadProject(); }, [id]);

  const handleSave = async () => {
    setSaving(true);
    try {
      const payload = {
        name: editForm.name, reference: editForm.reference,
        project_type: editForm.project_type, status: editForm.status,
        location: editForm.location, description: editForm.description,
        client_name: editForm.client_name,
        start_date: editForm.start_date || null,
        end_date: editForm.end_date || null,
        budget: editForm.budget || null,
        actual_expenses: editForm.actual_expenses || 0,
      };
      const res = await projectsAPI.update(id, payload);
      setProject(res.data); setEditForm(res.data);
      setEditing(false);
      toast.success('Projet mis à jour');
      projectsAPI.getBudgetStats(id).then(sRes => setStats(sRes.data)).catch(() => {});
    } catch (err) {
      const errors = err.response?.data;
      if (errors) {
        Object.entries(errors).forEach(([k, v]) => {
          const msgs = Array.isArray(v) ? v : [v];
          msgs.forEach(m => toast.error(`${k}: ${m}`));
        });
      } else {
        toast.error('Erreur lors de la sauvegarde');
      }
    } finally { setSaving(false); }
  };

  if (loading) return (
    <AppLayout>
      <div style={{ display:'flex', alignItems:'center', justifyContent:'center', minHeight:'60vh' }}>
        <div style={{ width:40, height:40, border:`3px solid ${T.orange}`, borderTopColor:'transparent', borderRadius:'50%', animation:'spin 1s linear infinite' }}/>
      </div>
    </AppLayout>
  );

  if (!project) return null;

  // Build tabs based on role
  const TABS = [
    { id:'overview', label:"📋 Vue d'ensemble", show: true },
    // Admin and Directeur see the rich Vue Ensemble tab instead of basic overview
    ...(isAdminOrDirecteur ? [
      { id:'vue_ensemble', label:"🏗️ Tableau de bord projet", show: true },
    ] : []),
    ...(canViewFinancials ? [{ id:'budget', label:`💰 Budget`, show: true }] : []),
    { id:'contracts', label:`📄 Contrats (${project.contracts?.length ?? 0})`, show: true },
    { id:'journal', label:'📓 Journal', show: true },
    { id:'team', label:'👥 Équipe', show: isAdminOrDirecteur },
  ].filter(t => t.show);

  const inputStyle = {
    width:'100%', padding:'9px 12px', borderRadius:8,
    border:`1px solid ${T.border}`, background:'#FAFAFA',
    fontSize:13, color:T.text, outline:'none', fontFamily:'inherit', boxSizing:'border-box',
  };

  return (
    <AppLayout projectName={project.name}>
      <div style={{ padding:'32px 36px', maxWidth:1100, margin:'0 auto' }}>

        {/* Back */}
        <button onClick={() => navigate('/projects')}
          style={{ background:'none', border:'none', color:T.textSub, fontSize:13, cursor:'pointer', marginBottom:20, display:'flex', alignItems:'center', gap:6, fontFamily:'inherit' }}>
          ← Retour aux projets
        </button>

        {/* Header */}
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:8 }}>
          <div style={{ display:'flex', alignItems:'center', gap:16, flex:1 }}>
            <span style={{ fontSize:36 }}>{TYPE_ICONS[project.project_type]||'🏗️'}</span>
            <div>
              <div style={{ display:'flex', alignItems:'center', gap:12, marginBottom:4 }}>
                <h1 style={{ fontSize:24, fontWeight:800, margin:0, color:T.text }}>{project.name}</h1>
                <StatusBadge status={project.status}/>
              </div>
              <div style={{ display:'flex', gap:16, color:T.textSub, fontSize:13, flexWrap:'wrap' }}>
                {project.reference  && <span>#{project.reference}</span>}
                {project.location   && <span>📍 {project.location}</span>}
                {project.client_name && <span>👤 {project.client_name}</span>}
                {project.start_date && <span>📅 Début: {new Date(project.start_date+'T00:00:00').toLocaleDateString('fr-FR')}</span>}
                {project.end_date   && <span>🏁 Fin: <span style={{ color:project.is_delayed?T.red:T.textSub }}>{new Date(project.end_date+'T00:00:00').toLocaleDateString('fr-FR')}</span></span>}
              </div>
            </div>
          </div>
          {isAdminOrDirecteur && (
            <div style={{ display:'flex', gap:10 }}>
              {editing ? (
                <>
                  <button onClick={() => { setEditing(false); setEditForm(project); }}
                    style={{ padding:'9px 18px', borderRadius:8, border:`1px solid ${T.border}`, background:'#fff', color:T.textSub, fontSize:13, cursor:'pointer', fontFamily:'inherit' }}>
                    Annuler
                  </button>
                  <button onClick={handleSave} disabled={saving}
                    style={{ padding:'9px 18px', borderRadius:8, background:T.orange, color:'#fff', fontSize:13, fontWeight:600, border:'none', cursor:'pointer', fontFamily:'inherit' }}>
                    {saving ? '⏳...' : '✅ Sauvegarder'}
                  </button>
                </>
              ) : (
                <>
                  <button onClick={() => navigate('/contracts/upload')}
                    style={{ padding:'9px 18px', borderRadius:8, background:T.blueLight||'#EFF6FF', color:T.blue, border:`1px solid ${T.blue}30`, fontSize:13, fontWeight:600, cursor:'pointer', fontFamily:'inherit' }}>
                    📤 Téléverser contrat IA
                  </button>
                  <button onClick={() => setEditing(true)}
                    style={{ padding:'9px 18px', borderRadius:8, border:`1px solid ${T.border}`, background:'#fff', color:T.textSub, fontSize:13, fontWeight:600, cursor:'pointer', fontFamily:'inherit' }}>
                    ✏️ Modifier
                  </button>
                </>
              )}
            </div>
          )}
        </div>

        {/* Tabs */}
        <div style={{ display:'flex', borderBottom:`1px solid ${T.border}`, marginBottom:28, marginTop:24, overflowX:'auto' }}>
          {TABS.map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id)}
              style={{
                padding:'11px 18px', fontSize:13, fontWeight:600, cursor:'pointer',
                background:'none', border:'none', outline:'none', fontFamily:'inherit',
                color:activeTab===tab.id?T.orange:T.textSub,
                borderBottom:`2px solid ${activeTab===tab.id?T.orange:'transparent'}`,
                marginBottom:-1, transition:'all 0.15s', whiteSpace:'nowrap',
              }}>
              {tab.label}
            </button>
          ))}
        </div>

        {/* Overview tab — general info + edit form */}
        {activeTab === 'overview' && (
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:20 }}>
            <Card>
              <div style={{ fontSize:14, fontWeight:700, color:T.orange, marginBottom:16 }}>📋 Informations générales</div>
              {editing ? (
                <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
                  <div>
                    <label style={{ display:'block', fontSize:11, fontWeight:600, color:T.textSub, marginBottom:5, textTransform:'uppercase', letterSpacing:'0.4px' }}>Nom *</label>
                    <input style={inputStyle} value={editForm.name||''} onChange={e => setEditForm(f=>({...f,name:e.target.value}))}/>
                  </div>
                  <div>
                    <label style={{ display:'block', fontSize:11, fontWeight:600, color:T.textSub, marginBottom:5, textTransform:'uppercase', letterSpacing:'0.4px' }}>Référence</label>
                    <input style={inputStyle} value={editForm.reference||''} onChange={e => setEditForm(f=>({...f,reference:e.target.value}))}/>
                  </div>
                  <div>
                    <label style={{ display:'block', fontSize:11, fontWeight:600, color:T.textSub, marginBottom:5, textTransform:'uppercase', letterSpacing:'0.4px' }}>Type</label>
                    <select style={inputStyle} value={editForm.project_type||'batiment'} onChange={e => setEditForm(f=>({...f,project_type:e.target.value}))}>
                      {PROJECT_TYPES.map(t=><option key={t.value} value={t.value}>{t.label}</option>)}
                    </select>
                  </div>
                  <div>
                    <label style={{ display:'block', fontSize:11, fontWeight:600, color:T.textSub, marginBottom:5, textTransform:'uppercase', letterSpacing:'0.4px' }}>Statut</label>
                    <select style={inputStyle} value={editForm.status||'planifie'} onChange={e => setEditForm(f=>({...f,status:e.target.value}))}>
                      <option value="planifie">Planifié</option>
                      <option value="en_cours">En cours</option>
                      <option value="suspendu">Suspendu</option>
                      <option value="termine">Terminé</option>
                    </select>
                  </div>
                  <div>
                    <label style={{ display:'block', fontSize:11, fontWeight:600, color:T.textSub, marginBottom:5, textTransform:'uppercase', letterSpacing:'0.4px' }}>Maître d'ouvrage</label>
                    <input style={inputStyle} value={editForm.client_name||''} onChange={e => setEditForm(f=>({...f,client_name:e.target.value}))}/>
                  </div>
                  <div>
                    <label style={{ display:'block', fontSize:11, fontWeight:600, color:T.textSub, marginBottom:5, textTransform:'uppercase', letterSpacing:'0.4px' }}>Localisation</label>
                    <input style={inputStyle} value={editForm.location||''} onChange={e => setEditForm(f=>({...f,location:e.target.value}))}/>
                  </div>
                  <div>
                    <label style={{ display:'block', fontSize:11, fontWeight:600, color:T.textSub, marginBottom:5, textTransform:'uppercase', letterSpacing:'0.4px' }}>Description</label>
                    <textarea style={{...inputStyle,minHeight:80,resize:'vertical'}} value={editForm.description||''} onChange={e => setEditForm(f=>({...f,description:e.target.value}))}/>
                  </div>
                </div>
              ) : (
                <>
                  <InfoRow label="Type"             value={project.project_type_display}/>
                  <InfoRow label="Référence"        value={project.reference}/>
                  <InfoRow label="Maître d'ouvrage" value={project.client_name}/>
                  <InfoRow label="Localisation"     value={project.location}/>
                  <InfoRow label="Description"      value={project.description}/>
                </>
              )}
            </Card>
            <div style={{ display:'flex', flexDirection:'column', gap:16 }}>
              <Card>
                <div style={{ fontSize:14, fontWeight:700, color:T.orange, marginBottom:16 }}>📅 Planning</div>
                {editing ? (
                  <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
                    <div>
                      <label style={{ display:'block', fontSize:11, fontWeight:600, color:T.textSub, marginBottom:5, textTransform:'uppercase', letterSpacing:'0.4px' }}>Date de début</label>
                      <input style={inputStyle} type="date" value={editForm.start_date||''} onChange={e => setEditForm(f=>({...f,start_date:e.target.value}))}/>
                    </div>
                    <div>
                      <label style={{ display:'block', fontSize:11, fontWeight:600, color:T.textSub, marginBottom:5, textTransform:'uppercase', letterSpacing:'0.4px' }}>Date de fin prévue</label>
                      <input style={inputStyle} type="date" value={editForm.end_date||''} onChange={e => setEditForm(f=>({...f,end_date:e.target.value}))}/>
                    </div>
                  </div>
                ) : (
                  <>
                    <InfoRow label="Début" value={project.start_date?new Date(project.start_date+'T00:00:00').toLocaleDateString('fr-FR',{day:'2-digit',month:'long',year:'numeric'}):null}/>
                    <InfoRow label="Fin prévue" value={project.end_date?<span style={{color:project.is_delayed?T.red:T.text}}>{new Date(project.end_date+'T00:00:00').toLocaleDateString('fr-FR',{day:'2-digit',month:'long',year:'numeric'})}{project.is_delayed?' ⚠️ RETARD':''}</span>:null}/>
                  </>
                )}
              </Card>
              <Card>
                <div style={{ fontSize:14, fontWeight:700, color:T.orange, marginBottom:16 }}>💰 Budget</div>
                {editing ? (
                  <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
                    <div>
                      <label style={{ display:'block', fontSize:11, fontWeight:600, color:T.textSub, marginBottom:5, textTransform:'uppercase', letterSpacing:'0.4px' }}>Budget prévisionnel (FCFA)</label>
                      <input style={inputStyle} type="number" min="0" value={editForm.budget||''} onChange={e => setEditForm(f=>({...f,budget:e.target.value}))}/>
                    </div>
                    <div>
                      <label style={{ display:'block', fontSize:11, fontWeight:600, color:T.textSub, marginBottom:5, textTransform:'uppercase', letterSpacing:'0.4px' }}>Dépenses réelles (FCFA)</label>
                      <input style={inputStyle} type="number" min="0" value={editForm.actual_expenses||''} onChange={e => setEditForm(f=>({...f,actual_expenses:e.target.value}))}/>
                    </div>
                  </div>
                ) : (
                  <>
                    <InfoRow label="Budget"    value={project.budget?fmtFCFA(project.budget):null}/>
                    <InfoRow label="Dépensé"   value={fmtFCFA(project.actual_expenses||0)}/>
                    <InfoRow label="Contrats"  value={`${project.contracts_count??0} contrat(s)`}/>
                    {project.budget_consumed_pct != null && (
                      <div style={{ marginTop:12 }}>
                        <Pbar pct={project.budget_consumed_pct} color={project.budget_consumed_pct>85?T.red:T.orange} h={6}/>
                        <div style={{ fontSize:11, color:T.textMuted, marginTop:4 }}>{project.budget_consumed_pct}% consommé</div>
                      </div>
                    )}
                  </>
                )}
              </Card>
            </div>
          </div>
        )}

        {/* Vue Ensemble — Directeur / Admin only */}
        {activeTab === 'vue_ensemble' && (
          <VueEnsemble project={project} stats={stats} contracts={project.contracts}/>
        )}

        {/* Budget tab */}
        {activeTab === 'budget' && (
          <BudgetTab stats={stats} project={project}/>
        )}

        {/* Contracts tab */}
        {activeTab === 'contracts' && (
          <ContractsTab contracts={project.contracts} projectId={id} onRefresh={loadProject}/>
        )}

        {/* Journal tab */}
        {activeTab === 'journal' && <JournalTab projectId={id}/>}

        {/* Team tab */}
        {activeTab === 'team' && <TeamTab projectId={id}/>}

      </div>
    </AppLayout>
  );
}
